// Generated by OpenCode AI - Changelog Timeline Client Component - 2026-02-09
'use client';

import { useEffect, useState } from 'react';

import { formatDate } from '@/lib/utils';

interface ChangelogEntry {
  url: string;
  data: {
    title: string;
    date: string;
    version?: string;
    tags?: string[];
    body: React.ComponentType;
  };
}

export function ChangelogTimeline() {
  const [changelogs, setChangelogs] = useState<ChangelogEntry[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadChangelogs() {
      try {
        const files = [
          'v1-5-1-hotfix',
          'v1-5-performance-boost',
          'v1-4-ai-coaching',
          'v1-3-social-features',
          'v1-2-analytics',
          'v1-1-nutrition',
          'v1-0-launch',
        ];

        const entries = await Promise.all(
          files.map(async (file) => {
            try {
              const mdxModule = await import(`@/content/changelog/${file}.mdx`);
              return {
                url: `/changelog/${file}`,
                data: {
                  title: mdxModule.frontmatter?.title || 'Untitled',
                  date: mdxModule.frontmatter?.date || '',
                  version: mdxModule.frontmatter?.version || undefined,
                  tags: mdxModule.frontmatter?.tags || [],
                  body: mdxModule.default,
                },
              } as ChangelogEntry;
            } catch (error) {
              console.error(`Failed to load ${file}:`, error);
              return null;
            }
          })
        );

        const validEntries = entries.filter(
          (entry): entry is ChangelogEntry => entry !== null
        );

        const sorted = validEntries.sort((a, b) => {
          const dateA = new Date(a.data.date).getTime();
          const dateB = new Date(b.data.date).getTime();
          return dateB - dateA;
        });

        setChangelogs(sorted as ChangelogEntry[]);
      } catch (error) {
        console.error('Failed to load changelogs:', error);
      } finally {
        setLoading(false);
      }
    }

    loadChangelogs();
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="text-lg text-muted-foreground">
          Loading changelog...
        </div>
      </div>
    );
  }

  if (changelogs.length === 0) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="text-lg text-muted-foreground">
          No changelog entries found.
        </div>
      </div>
    );
  }

  return (
    <div className="relative">
      {changelogs.map((entry) => {
        const MDX = entry.data.body;
        const date = new Date(entry.data.date);
        const formattedDate = formatDate(date);

        return (
          <div key={entry.url} className="relative">
            <div className="flex flex-col gap-y-6 md:flex-row">
              <div className="flex-shrink-0 md:w-48">
                <div className="pb-10 md:sticky md:top-8">
                  <time className="mb-3 block font-medium text-muted-foreground text-sm">
                    {formattedDate}
                  </time>

                  {entry.data.version && (
                    <div className="relative z-10 inline-flex h-10 w-10 items-center justify-center rounded-lg border border-border font-bold text-foreground text-sm">
                      {entry.data.version}
                    </div>
                  )}
                </div>
              </div>

              {/* Right side - Content */}
              <div className="relative flex-1 pb-10 md:pl-8">
                {/* Vertical timeline line */}
                <div className="absolute top-2 left-0 hidden h-full w-px bg-border md:block">
                  {/* Timeline dot */}
                  <div className="absolute z-10 hidden size-3 -translate-x-1/2 rounded-full bg-primary md:block" />
                </div>

                <div className="space-y-6">
                  <div className="relative z-10 flex flex-col gap-2">
                    <h2 className="text-balance font-semibold text-2xl tracking-tight">
                      {entry.data.title}
                    </h2>

                    {/* Tags */}
                    {entry.data.tags && entry.data.tags.length > 0 && (
                      <div className="flex flex-wrap gap-2">
                        {entry.data.tags.map((tag: string) => (
                          <span
                            key={tag}
                            className="flex h-6 w-fit items-center justify-center rounded-full border bg-muted px-2 font-medium text-muted-foreground text-xs"
                          >
                            {tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                  <div className="prose dark:prose-invert max-w-none prose-headings:scroll-mt-8 prose-headings:text-balance prose-p:text-balance prose-headings:font-semibold prose-headings:tracking-tight prose-p:tracking-tight prose-a:no-underline">
                    <MDX />
                  </div>
                </div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}
